import * as kitModule from '../../scripts/figures/kit/iso-kit.mjs';

/**
 * The Anatomy figures (generated by scripts/figures/*.mjs) and the pieces
 * IsoFigure and the /figures/ endpoints need: the frame (plate, labels and
 * steps, with the drawing taken out), the drawing itself, and the live
 * script wrapped so it can run as a module or inline.
 */
export type FigureName = 'data-vault' | 'chain-rack' | 'pavii-gates' | 'cipher-tower';

const html = import.meta.glob('../components/home/figures/*.html', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;
const live = import.meta.glob('../components/home/figures/*.live.js', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;

export const figureNames = Object.keys(html).map(path => path.match(/([a-z-]+)\.html$/)![1] as FigureName);

export function figureParts(name: FigureName) {
  const markup = html[`../components/home/figures/${name}.html`];
  const [, vw, vh] = markup.match(/viewBox="0 0 (\d+) (\d+)"/) ?? [];
  const open = markup.indexOf(`data-figure="${name}">`) + `data-figure="${name}">`.length;
  const close = markup.indexOf('</div>', open);
  return {
    markup,
    ratio: vw && vh ? Number(vw) / Number(vh) : 1.7,
    /** The frame with an empty, correctly sized box where the drawing goes. */
    shell: `${markup.slice(0, open)}<div class="iso-placeholder" style="aspect-ratio:${vw}/${vh}"></div>${markup.slice(close)}`,
    /** The drawing and its labels, loaded into that box later. */
    stage: markup.slice(open, close),
  };
}

/** The live script as a function body: runs once per stage, kit in scope. */
export function figureScript(name: FigureName) {
  const source = live[`../components/home/figures/${name}.live.js`].replace(
    /for \(const stage of document\.querySelectorAll\('(\[data-figure="[a-z-]+"\])'\)\) \{/,
    "for (const stage of document.querySelectorAll('$1:not([data-iso-ready])')) { stage.setAttribute('data-iso-ready', '');"
  );
  const names = Object.keys(kitModule).join(', ');
  return `{
const run = () => {
const { ${names} } = window.IsoKit;
${source}
};
(window.__isoRun ||= {})[${JSON.stringify(name)}] = run;
window.IsoKit ? run() : window.addEventListener('isokit', run, { once: true });
}`;
}
